<?php
class Reporte_cortesias extends CI_Controller{
 private $session_data=array();
 public function __construct(){parent::__construct();if(!$this->session->userdata('logged_in'))redirect('','refresh');$this->session_data=$this->session->userdata('logged_in');$this->load->model('Reporte_cortesias_model');$this->load->model('Sistema_model');$this->load->model('Parametro_model');if(!$this->Reporte_cortesias_model->usuario_tiene_rol((int)$this->session_data['usuario_id'],220))show_error('No tiene permiso para generar reportes de Transporte.',403,'Acceso denegado');}
 private function filtros(){ $d=trim((string)$this->input->get('desde',true));$h=trim((string)$this->input->get('hasta',true));if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$d))$d=date('Y-m-01');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$h))$h=date('Y-m-d');if($d>$h){$x=$d;$d=$h;$h=$x;}return array('desde'=>$d,'hasta'=>$h,'usuario_id'=>(int)$this->input->get('usuario_id',true),'ruta_id'=>(int)$this->input->get('ruta_id',true),'motivo_id'=>(int)$this->input->get('motivo_id',true));}
 public function index(){ $f=$this->filtros();$p=$this->Parametro_model->get_parametros();$data['sistema']=$this->Sistema_model->get_sistema();$data['parametro']=isset($p[0])?$p[0]:$p;$data['filtros']=$f;$data['listas']=$this->Reporte_cortesias_model->listas();$data['resumen']=$this->Reporte_cortesias_model->resumen($f);$data['detalle']=$this->Reporte_cortesias_model->detalle($f);$data['page_title']='Reporte de cortesías';$data['_view']='reporte_transporte/cortesias';$this->load->view('layouts/main',$data);}
 public function csv(){ $f=$this->filtros();$rs=$this->Reporte_cortesias_model->detalle($f);header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="cortesias_'.$f['desde'].'_'.$f['hasta'].'.csv"');echo "\xEF\xBB\xBF";$x=fopen('php://output','w');fputcsv($x,array('Fecha','Ticket','Pasajero','Documento','Ruta','Motivo cortesía','Tarifa original','Importe cobrado','Usuario'),';');foreach($rs as $r)fputcsv($x,array($r['fecha'],$r['ticket'],$r['pasajero'],$r['documento'],$r['ruta'],$r['motivo'],$r['tarifa_original'],$r['importe_cobrado'],$r['usuario']),';');fclose($x);exit;}
}
